import React, { useEffect, useState, useRef } from 'react';
import { SKILLS } from '../constants';

const BarChart: React.FC = () => {
  return (
    <div className="w-full space-y-6 py-8">
      {SKILLS.map((skill, i) => (
        <div key={i} className="space-y-2">
